// Kronos Bot — sync de settings.capital_real (STATUS.md punto 17).
// orders/status.json lo reescribe el EA en cada ciclo de
// WritePositionsStatus() con account.capital_real = AccountBalance()
// completo (decisión explícita del usuario, 2026-08-28: incluye
// crédito del bróker). Mismo patrón filesystem-v2 que el resto de
// nodos readWriteFile de este proyecto (getBinaryDataBuffer, no
// item.binary.data.data en base64).
const items = $input.all();
if (items.length === 0) return [];

const buffer = await this.helpers.getBinaryDataBuffer(0, 'data');
const parsed = JSON.parse(buffer.toString('utf-8'));
const capitalReal = parsed && parsed.account ? Number(parsed.account.capital_real) : NaN;

if (!isFinite(capitalReal)) return [];

return [{ json: { capital_real: capitalReal } }];
